import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.simplepoint.platform.composition.ModuleCatalog;
import org.simplepoint.platform.composition.ModuleHttpPlan;
import org.simplepoint.platform.composition.ModuleMigrations;
import org.simplepoint.plugin.rbac.http.IdentityHttpModule;

public class VerifyIdentityHttpArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyIdentityHttpArtifacts.class.getClassLoader();
    var catalog = ModuleCatalog.discover(loader);
    var domain = catalog.plan(List.of("identity", "oidc", "i18n"));
    if (!ModuleHttpPlan.from(domain).routes().isEmpty())
      throw new AssertionError("Domain-only selection exposes HTTP");
    var selected = ModuleHttpPlan.from(catalog.plan(List.of("identity-http", "oidc-http", "i18n-http")));
    if (!selected.routes().keySet().equals(Set.of("identity-http", "oidc-http", "i18n-http")))
      throw new AssertionError("Missing adapter in installed catalog");
    if (IdentityHttpModule.class.getAnnotation(ModuleMigrations.class).ownsSchema())
      throw new AssertionError("HTTP adapter incorrectly owns a schema");
    var controllers = Files.readAllLines(Path.of(args[0]));
    if (controllers.size() != 20) throw new AssertionError("Wrong moved controller count");
    for (String name : controllers) {
      Class<?> type = Class.forName(name, false, loader);
      if (domain.ownerOf(type).isPresent()
          || !selected.ownerOf(type).orElseThrow().equals("identity-http")
          || !selected.namespaceOf(type).orElseThrow().equals("/common"))
        throw new AssertionError("Incorrect selected ownership: " + name);
      var urls = Collections.list(loader.getResources(name.replace('.', '/') + ".class"));
      if (urls.size() != 1 || !urls.getFirst().toString().contains("/simplepoint-plugin-rbac-http.jar!"))
        throw new AssertionError("Controller duplicated or packaged in wrong artifact: " + name);
    }
    System.out.println("Installed distribution: 20 unique relocated controllers, domain-only isolation, three optional adapters, no HTTP schema ownership; identity subtree count=" + selected.routes().get("identity-http").size());
  }
}
